mapper.select:
SELECT um.user_id, um.user_name, um.dept, dm.dept_name, ccj.code_name as job_title, ccp.code_name as position FROM tb_user_master um JOIN tb_dept_master dm ON dm.dept_code = um.dept JOIN tb_cm_code ccj ON ccj.code = um.job_title JOIN tb_cm_code ccp ON ccp.code = um.position WHERE 1=1 AND um.leave_date IS NULL
AND um.company_code = '0000'
AND um.company_code = #{companyCode}
AND dm.dept_name = #{text}
